path = Path(__file__).with_name('catalog.json')
catalog = json.loads(path.read_text(encoding='utf-8'))
assert set(rows) == set(catalog['locales'])
for i, key in enumerate(keys):
    if key not in catalog['keys']:
        catalog['keys'].append(key)
        for tag, values in catalog['locales'].items(): values.append(rows[tag][i])
    else:
        index = catalog['keys'].index(key)
        for tag, values in catalog['locales'].items(): values[index] = rows[tag][i]
# Notes privacy depends on the chosen output; never imply that an opted-in PPTX stays private.
